D.CatalogStrings[31680]="纳鲁是接近于神的能量体族群，与圣光有着密切的联系。当先知维伦祈求援助，希望能让族人免于受到燃烧军团腐蚀的时候，纳鲁第一次出现在德莱尼面前。他们回应了维伦的恳求，帮助他带领族人踏上逃亡之路。“德莱尼”这个名字的意思就是“流亡者”。"
D.CatalogStrings[31681]="你立刻就能判断出来，这只酒杯存在的意义远大于一个用于喝酒的器皿（虽然喝酒本身对于矮人来说已经具有极为重要的意义了）。你能够从上面解读出的一点文字代表着某种庄严的仪式。"
