D.CatalogStrings[32826]="铁炉堡矮人最初由三个部族组成：铜须、蛮锤和黑铁。经过一次激烈的内战，铜须部族完全掌握了铁炉堡。蛮锤部族撤退到辛特兰和暮光高地。黑铁矮人定居于赤脊山和燃烧平原之间，黑石山的阴影中。"
