D.CatalogStrings[34716]="艾泽拉斯的兽人原先居住在德拉诺世界。绝大多数兽人古物都来自于那里。兽人原本是爱好和平的种族，但在燃烧军团的影响下，他们变成了一群疯狂嗜血的战士。通过黑暗之门，兽人来到艾泽拉斯，与联盟进行了两场大战。而一场新的战争也许正在酝酿之中。"
