D.CatalogStrings[35558]="荣誉点数是通过在PvP战斗中进行荣誉击杀获得的。杀死敌人可以获得多少点数取决于你（或你所在的队伍）对其造成了多少伤害，并由你所在的小队或团队均分。如果你在短时间内反复杀死同一个敌方玩家，则每次杀死他所获得的荣誉点数也会越来越少，因此，在数次杀死同一个敌方玩家之后，你将获得极少的荣誉点数，甚至不再获得任何荣誉点数。"
