D.CatalogStrings[35580]="这是一个专门训练飞行兽并提供飞行运输服务的飞行管理员。只需一小笔花费，你就可以快速地飞往任何你曾经接触过的飞行管理员那里。|n|n当你发现一座新的城镇之后，最好先去找到该城镇的飞行管理员，以便日后能够快速抵达这里。"
