D.CatalogStrings[35587]="你加入了一个团队（可以容纳最多40人的队伍，但通常由10人或25人组成）。挑战最危险的地下城或最强大的敌人，特别是高等级的敌人，都需要由团队来完成。\n\n|cffff2020当你在一个团队中时，就无法完成大多数非团队任务。要离开一个团队，右键点击你的角色头像并选择离开队伍。|r"
