D.CatalogStrings[36843]="通常导致延迟的原因是一个地区内的玩家数量过多，如大城市或战场。从你的计算机到游戏服务器的连接延迟过高也会导致这一问题。发送此报告将帮助我们侦测并有可能解决你所遇到的延迟问题。\\n\\n你现在遇到的是哪种延迟？请点击下方按钮，发送相关报告。"
