D.CatalogStrings[38466]="科赞岛上的地精曾经是丛林巨魔的奴隶，被强迫开采深埋于卡亚罗山脉地底的卡亚矿石。然而不为人知的是，这些矿物具有某种神秘的魔法效力，受其影响的地精很快就变得既聪明又狡猾。醉心于工程学和炼金术，地精秘密地发明出了各式威力强大的神奇道具，并借此推翻了巨魔主人的统治，在科赞岛上建立了自己的家园。在那之后，地精大师级的商事手腕迅速崭露头角，他们的环球贸易寡头公司支配着整个艾泽拉斯世界的商业。"
