D.CatalogStrings[38774]="一万年前，暗夜精灵就已经建立了一个庞大的帝国，但是他们无节制地滥用魔法，最终导致了帝国的毁灭。幸存的暗夜精灵怀着悲伤重新回到了森林中，过起了与世隔绝的隐居生活，直到他们过去的敌人燃烧军团重新来到这个世界。现在，别无选择的暗夜精灵重新开始和外界接触，为了自己的种族能在这个新的世界中生存下去而战斗着。"
