D.CatalogStrings[40164]="千百年来，不散的迷雾一直笼罩着潘达利亚，让这个古老的国度远离战火的纷扰。如今迷雾已经散去，熊猫人英雄纷纷踏上了冒险的旅程，他们将选择与联盟或是部落并肩作战。最具冒险精神的熊猫人来自迷踪岛——这是一座与世隔绝，行踪不明的神秘岛屿，既不在潘达利亚，也不属于艾泽拉斯的任何已知版图。"
